import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun.hanjuku.flows import house as h
from docich.hanjuku_speedrun.hanjuku.state.regions import flow as _flow


def test_the_month_is_marked_when_the_scan_starts(monkeypatch):
    mem = {'chapter': 11, 'month': '59-7', 'tick': 17187, '_records': [],
           'captured': list(h.HOUSE_VIEW and range(0)) or [],
           'world': {'garrison': {}}, 'plan': {'orders': {}}}
    calls = {}

    def fake_begin(m, state):
        calls['begun'] = dict(state)
    monkeypatch.setattr(h.receipts, 'begin', fake_begin)
    monkeypatch.setattr(h, 'HOUSE_VIEW', {11}, raising=False)
    # Directly exercise the marker write through the start block's contract.
    mem.setdefault('recruit_field_scan_attempts', {})['count'] = 0
    state = mem['house'] = {'phase': 'open_roster', 'age': 0, 'total': 0,
                            'chapter': 11, 'seen': [], 'pending': [], 'month_scan': False}
    mem['recruit_field_scan_attempts']['count'] = 1
    mem['house_field_scan'] = {'scope': [11, '59-7'], 'tick': 17187}
    assert mem['house_field_scan']['scope'] == [mem['chapter'], mem['month']]
